def most_frequent_elements(input_list: list) -> list:
    if not input_list:
        return []

    frequency = {}
    for num in input_list:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_count = max(frequency.values())
    most_frequent = [num for num, count in frequency.items() if count == max_count]

    return sorted(most_frequent)
```

