def find_all_anagrams(s: str, p: str):
    """
    This function finds all starting indices of p's anagrams in s.
    """
    from collections import Counter

    p_count = Counter(p)
    s_count = Counter()
    result = []

    for i in range(len(s)):
        s_count[s[i]] += 1

        if i >= len(p):
            if s_count[s[i - len(p)]] == 1:
                del s_count[s[i - len(p)]]
            else:
                s_count[s[i - len(p)]] -= 1

        if s_count == p_count:
            result.append(i - len(p) + 1)

    return result
```

