    def is_valid_path(path):
        return all(min_weight <= weight <= max_weight for _, weight in path)

    def find_path_dijkstra(graph, start, target, min_weight, max_weight):
        pq = [(0, [start])]
        visited = set()
        while pq:
            (cost, path) = heapq.heappop(pq)
            node = path[-1]
            if node == target and is_valid_path(path):
                return path
            if node not in visited:
                visited.add(node)
                for neighbor, weight in graph[node]:
                    if neighbor not in visited and min_weight <= weight <= max_weight:
                        heapq.heappush(pq, (cost + weight, path + [neighbor]))
        return []

    return find_path_dijkstra(adj_list, start, target, min_weight, max_weight)
