import heapq

def constrained_shortest_path(adj_list: Dict[str, List[Tuple[str, int]]], start: str, target: str, min_weight: int, max_weight: int) -> List[str]:
    # Priority queue to store the nodes to be explored
    pq = [(0, start, [start])]
    # Dictionary to store the minimum distance to each node
    dist = {start: 0}

    while pq:
        current_dist, current_node, path = heapq.heappop(pq)

        # If the current node is the target, return the path
        if current_node == target:
            return path

        # Explore the neighbors
        for neighbor, weight in adj_list.get(current_node, []):
            if min_weight <= weight <= max_weight:
                new_dist = current_dist + weight
                if neighbor not in dist or new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor, path + [neighbor]))

    # If no path is found, return an empty list
    return []
