def constrained_shortest_path(adj_list: Dict[str, List[Tuple[str, int]]], start: str, target: str, min_weight: int, max_weight: int) -> List[str]:
    def is_valid_path(path):
        for i in range(len(path) - 1):
            for dest, weight in adj_list[path[i]]:
                if dest == path[i + 1] and not (min_weight <= weight <= max_weight):
                    return False
        return True

    def dijkstra():
        pq = [(0, start, [start])]
        visited = set()
        while pq:
            dist, node, path = heapq.heappop(pq)
            if node == target and is_valid_path(path):
                return path
            if node in visited:
                continue
            visited.add(node)
            for neighbor, weight in adj_list[node]:
                if neighbor not in visited and min_weight <= weight <= max_weight:
                    heapq.heappush(pq, (dist + weight, neighbor, path + [neighbor]))
        return []

    return dijkstra()
