def is_isomorphic(s1: str, s2: str) -> bool:
    if len(s1) != len(s2):
        return False

    char_map = {}
    used_chars = set()

    for char1, char2 in zip(s1, s2):
        if char1 in char_map:
            if char_map[char1] != char2:
                return False
        else:
            if char2 in used_chars:
                return False
            char_map[char1] = char2
            used_chars.add(char2)

    return True
