def evaluate_expression(expression: str) -> int:
    import re
    from operator import add, sub, mul, truediv

    # Helper function to apply an operator to the top two elements of the stack
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(add(left, right))
        elif operator == '-':
            values.append(sub(left, right))
        elif operator == '*':
            values.append(mul(left, right))
        elif operator == '/':
            values.append(int(truediv(left, right)))

    # Tokenize the input expression
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\(|\)', expression)

    # Stack for operators and stack for values
    operators = []
    values = []

    # Precedence of operators
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if token.isdigit():
            values.append(int(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove the '('
        else:
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[token]):
                apply_operator(operators, values)
            operators.append(token)

    # Apply remaining operators
    while operators:
        apply_operator(operators, values)

    return values[0]
