    def compute_pi_table(pattern: str) -> list:
        pi = [0] * len(pattern)
        j = 0
        for i in range(1, len(pattern)):
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                pi[i] = j
        return pi

    def search(text: str, pattern: str, pi: list) -> list:
        result = []
        j = 0
        for i in range(len(text)):
            while j > 0 and text[i] != pattern[j]:
                j = pi[j - 1]
            if text[i] == pattern[j]:
                j += 1
                if j == len(pattern):
                    result.append(i - j + 1)
                    j = pi[j - 1]
        return result

    pi_table = compute_pi_table(pattern)
    return search(text, pattern, pi_table)
