def can_form_palindrome(s: str) -> bool:
    # Dictionary to count occurrences of each character
    char_count = {}

    # Count each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check the number of characters with odd counts
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # A string can be rearranged to form a palindrome if it has at most one character with an odd count
    return odd_count <= 1
```

