def calculate_binary_gap(number: int) -> int:
    if not isinstance(number, int) or number < 0:
        raise TypeError("Input value must be a non-negative 'int' type")

    max_gap = 0
    current_gap = 0
    found_one = False

    while number > 0:
        bit = number & 1
        if bit == 1:
            if found_one:
                max_gap = max(max_gap, current_gap)
                current_gap = 0
            found_one = True
        elif found_one:
            current_gap += 1
        number >>= 1

    return max_gap
```

