from heapq import heappush, heappop

def shortest_path_with_stops(graph: dict, start: str, end: str, max_stops: int) -> int:
    pq = [(0, start, 0)]  # (current_weight, current_node, current_stops)
    visited = set()

    while pq:
        current_weight, current_node, current_stops = heappop(pq)

        if current_node == end:
            return current_weight

        if current_node in visited and current_stops <= visited[current_node]:
            continue

        visited.add(current_node)

        if current_stops < max_stops:
            for neighbor, weight in graph.get(current_node, []):
                if neighbor not in visited or current_stops + 1 < visited[neighbor]:
                    heappush(pq, (current_weight + weight, neighbor, current_stops + 1))

    return -1
```

