from collections import deque

def shortest_path_with_stops(graph: dict, start: str, end: str, max_stops: int) -> int:
    if start == end:
        return 0

    queue = deque([(start, 0, 0)])  # (current_node, current_weight, current_stops)
    visited = set()

    while queue:
        current_node, current_weight, current_stops = queue.popleft()

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph.get(current_node, []):
            if current_stops + 1 <= max_stops:
                if neighbor == end:
                    return current_weight + weight
                queue.append((neighbor, current_weight + weight, current_stops + 1))

    return -1
```

