        # Initialize a list to store the minimum coins needed for each amount up to the target amount
        dp = [self.max_value] * (amount + 1)
        dp[0] = 0  # Base case: 0 coins are needed to make amount 0

        # Iterate over each amount from 1 to the target amount
        for i in range(1, amount + 1):
            # Check each coin denomination
            for coin in self.coins:
                if i >= coin:
                    dp[i] = min(dp[i], dp[i - coin] + 1)

        # If dp[amount] is still max_value, it means it's not possible to make that amount
        return dp[amount] if dp[amount] != self.max_value else -1
