class CoinChange:
    def __init__(self, coins: list[int]):
        self.coins = coins
        self.dp = [-1] * (amount + 1)

    def min_coins(self, amount: int) -> int:
        if amount == 0:
            return 0
        if self.dp[amount] != -1:
            return self.dp[amount]

        min_coins = float('inf')
        for coin in self.coins:
            if amount - coin >= 0:
                result = self.min_coins(amount - coin)
                if result != -1:
                    min_coins = min(min_coins, result + 1)

        if min_coins == float('inf'):
            self.dp[amount] = -1
        else:
            self.dp[amount] = min_coins

        return self.dp[amount]
