import operator

def evaluate_expression(expression):
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}
    stack = []
    current_number = 0
    current_operator = '+'

    for char in expression:
        if char.isdigit():
            current_number = current_number * 10 + int(char)
        elif char in ops:
            if current_operator == '+':
                stack.append(current_number)
            elif current_operator == '-':
                stack.append(-current_number)
            elif current_operator == '*':
                stack.append(stack.pop() * current_number)
            elif current_operator == '/':
                stack.append(int(stack.pop() / current_number))
            current_operator = char
            current_number = 0
        elif char == '(':
            stack.append(current_number)
            stack.append(current_operator)
            current_number = 0
            current_operator = '+'
        elif char == ')':
            while stack[-1] != '(':
                right = stack.pop()
                op = stack.pop()
                left = stack.pop()
                stack.append(ops[op](left, right))
            stack.pop()  # Remove the '('
            if stack and stack[-1] in ops:
                right = stack.pop()
                op = stack.pop()
                left = stack.pop()
                stack.append(ops[op](left, right))

    if current_operator == '+':
        stack.append(current_number)
    elif current_operator == '-':
        stack.append(-current_number)
    elif current_operator == '*':
        stack.append(stack.pop() * current_number)
    elif current_operator == '/':
        stack.append(int(stack.pop() / current_number))

    while len(stack) > 1:
        right = stack.pop()
        op = stack.pop()
        left = stack.pop()
        stack.append(ops[op](left, right))

    return stack[0]
