def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    # Create a graph using adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v, w in links:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Helper function to perform Dijkstra's algorithm
    def dijkstra(start):
        distances = [float('inf')] * (n + 1)
        distances[start] = 0
        pq = [(0, start)]
        while pq:
            current_distance, u = heapq.heappop(pq)
            if current_distance > distances[u]:
                continue
            for v, weight in graph[u]:
                distance = current_distance + weight
                if distance < distances[v]:
                    distances[v] = distance
                    heapq.heappush(pq, (distance, v))
        return max(distances[1:])

    # Binary search for the minimum possible maximum latency
    left, right = 1, 100
    while left < right:
        mid = (left + right) // 2
        if all(dijkstra(i) <= mid for i in range(1, n + 1)):
            right = mid
        else:
            left = mid + 1

    return left
```

