from typing import List, Tuple
import heapq

def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)

        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

    def kruskal():
        parent = list(range(n))
        rank = [0] * n
        result = []
        i = 0
        e = 0

        links.sort(key=lambda item: item[2])

        while e < n - 1:
            u, v, w = links[i]
            i += 1
            x = find(parent, u)
            y = find(parent, v)

            if x != y:
                e += 1
                result.append([u, v, w])
                union(parent, rank, x, y)

        return result

    def bfs(graph, start):
        visited = [False] * n
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor, weight in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return visited

    def max_latency(graph):
        max_latency = 0
        for i in range(n):
            visited = bfs(graph, i)
            if not all(visited):
                return float('inf')
            max_latency = max(max_latency, max([graph[i][j][1] for j in range(n) if visited[j]]))
        return max_latency

    if not links:
        return 0

    optimized_links = kruskal()
    graph = [[] for _ in range(n)]
    for u, v, w in optimized_links:
        graph[u].append((v, w))
        graph[v].append((u, w))

    return max_latency(graph)
