def minimize_max_latency(n: int, links: List[Tuple[int, int, int]]) -> int:
    def bfs(start):
        visited = [False] * (n + 1)
        queue = [(0, start)]
        max_latency = 0
        while queue:
            current_latency, current_node = heapq.heappop(queue)
            if not visited[current_node]:
                visited[current_node] = True
                max_latency = max(max_latency, current_latency)
                for neighbor, weight in graph[current_node]:
                    if not visited[neighbor]:
                        heapq.heappush(queue, (current_latency + weight, neighbor))
        return max_latency

    graph = [[] for _ in range(n + 1)]
    for u, v, w in links:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_latency = float('inf')
    for i in range(1, n + 1):
        min_latency = min(min_latency, bfs(i))

    return min_latency
