def find_sum_combinations(numbers: list[int], target_sum: int) -> list[list[int]]:
    def backtrack(start, path, current_sum):
        if current_sum == target_sum:
            result.append(path)
            return
        if current_sum > target_sum:
            return
        for i in range(start, len(numbers)):
            backtrack(i, path + [numbers[i]], current_sum + numbers[i])

    numbers.sort()
    result = []
    backtrack(0, [], 0)
    return result
