from typing import List

def calculate_moving_median(temperatures: List[float], window_size: int) -> List[float]:
    if window_size <= 0:
        raise ValueError("Window size must be greater than 0")

    if not temperatures:
        return []

    moving_medians = []
    window = []

    for i, temp in enumerate(temperatures):
        window.append(temp)
        window.sort()

        if len(window) > window_size:
            window.pop(0)

        if len(window) == window_size:
            if window_size % 2 == 1:
                median = window[window_size // 2]
            else:
                median = (window[window_size // 2 - 1] + window[window_size // 2]) / 2.0
            moving_medians.append(median)

    return moving_medians
```

