def evaluate_expression(expression):
    import operator
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}
    nums = list(map(int, expression.split('*')))
    result = nums[0]
    for i in range(1, len(nums)):
        result = ops['*'](result, nums[i])
    for op, num in zip(expression.split('*')[1:], expression.split('*')[2:]):
        if op == '+':
            result += int(num)
        elif op == '-':
            result -= int(num)
        elif op == '*':
            result *= int(num)
        elif op == '/':
            result /= int(num)
    return result
```

