import operator

def evaluate_expression(expression):
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}
    tokens = expression.split()
    stack = []
    for token in tokens:
        if token in ops:
            while stack and stack[-1] != '(':
                b = stack.pop()
                a = stack.pop()
                stack.append(ops[token](a, b))
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack[-1] != '(':
                b = stack.pop()
                a = stack.pop()
                stack.append(ops[stack.pop()](a, b))
            stack.pop()  # Remove the '('
        else:
            stack.append(int(token))
    while stack:
        b = stack.pop()
        a = stack.pop()
        stack.append(ops[stack.pop()](a, b))
    return stack[0]
