def min_steps_to_target(target: int) -> int:
    target = abs(target)
    step = 0
    current_sum = 0
    while current_sum < target:
        step += 1
        current_sum += step
    if current_sum == target:
        return step
    else:
        return step + (current_sum - target) % 2
