import operator
import re

def evaluate_expression(expression: str) -> float:
    # Define operator precedence and associativity
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    associativity = {'+': 'left', '-': 'left', '*': 'left', '/': 'left'}

    # Split the expression into tokens
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\(|\)', expression)

    # Function to apply an operator to two operands
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(operator(left, right))
        elif operator == '-':
            values.append(operator(left, right))
        elif operator == '*':
            values.append(operator(left, right))
        elif operator == '/':
            values.append(operator(left, right))

    # Function to process operators
    def process_operator(operators, values, token):
        while (operators and operators[-1] != '(' and
               (precedence[operators[-1]] > precedence[token] or
                (precedence[operators[-1]] == precedence[token] and associativity[token] == 'left'))):
            apply_operator(operators, values)
        operators.append(token)

    # Stack for operators and values
    operators = []
    values = []

    for token in tokens:
        if token.isdigit():
            values.append(int(token))
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        else:
            process_operator(operators, values, token)

    while operators:
        apply_operator(operators, values)

    return values[0]
