from typing import List

def can_dry_reservoir(rains: List[int]) -> bool:
    # Dictionary to store the last day it rained at each lake
    last_rain = {}
    # Set to store the lakes that need drying
    lakes_needing_drying = set()

    for day, rain in enumerate(rains):
        if rain < 0:
            lake = -rain
            if lake in last_rain:
                if lake not in lakes_needing_drying:
                    lakes_needing_drying.add(lake)
                else:
                    return False
            last_rain[lake] = day
        elif rain > 0:
            if lakes_needing_drying:
                lakes_needing_drying.remove(rain)

    return not lakes_needing_drying
