def reverse_words(s: str) -> str:
    words = s.split()
    reversed_words = words[::-1]
    result = []
    word_iter = iter(reversed_words)
    for char in s:
        if char.isalpha():
            result.append(next(word_iter))
        else:
            result.append(char)
    return ''.join(result)
```

