from collections import defaultdict
from datetime import datetime, timedelta

def aggregate_sensor_data(readings: list[tuple[str, float]]) -> dict:
    aggregated_data = defaultdict(float)
    counts = defaultdict(int)

    for timestamp, value in readings:
        dt = datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
        start_of_hour = dt.replace(minute=0, second=0, microsecond=0)
        aggregated_data[start_of_hour] += value
        counts[start_of_hour] += 1

    result = {ts: aggregated_data[ts] / counts[ts] for ts in aggregated_data if counts[ts] > 0}
    return result

# Unit tests
def test_aggregate_sensor_data():
    assert aggregate_sensor_data([]) == {}
    assert aggregate_sensor_data([("2023-03-25 14:00:00", 22.4)]) == {"2023-03-25 14:00:00": 22.4}
    assert aggregate_sensor_data([("2023-03-25 14:00:00", 22.4), ("2023-03-25 14:01:00", 24.1)]) == {"2023-03-25 14:00:00": 23.25}
    assert aggregate_sensor_data([("2023-03-25 14:00:00", 22.4), ("2023-03-25 15:00:00", 23.9)]) == {"2023-03-25 14:00:00": 22.4, "2023-03-25 15:00:00": 23.9}
    assert aggregate_sensor_data([("2023-03-25 14:00:00", 22.4), ("2023-03-25 14:00:00", 24.1)]) == {"2023-03-25 14:00:00": 23.25}

test_aggregate_sensor_data()
