def count_pairs(nums, k):
    seen = set()
    pairs = set()
    for num in nums:
        complement = k - num
        if complement in seen:
            # Ensure the smaller number comes first to avoid duplicate pairs
            pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)
    return len(pairs)
```

