from typing import List

def is_valid_inventory_sequence(operations: List[str]) -> bool:
    add_count = 0
    remove_count = 0
    inventory = []

    for operation in operations:
        parts = operation.split(':')
        if parts[0] == 'add':
            item_type = parts[1]
            inventory.append(item_type)
            add_count += 1
        elif parts[0] == 'remove':
            item_type = parts[1]
            if item_type in inventory:
                inventory.remove(item_type)
                remove_count += 1
            else:
                return False

        if remove_count > add_count:
            return False

    return add_count == remove_count
```

