    def dfs(node, parent):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if neighbor in visited:
                return True
            if dfs(neighbor, node):
                return True
        return False

    # Check for cycles in each component
    visited = set()
    for node in range(n):
        if node not in visited:
            if dfs(node, -1):
                return True
    return False
