import heapq

def find_shortest_route(locations: list[str], routes: list[tuple[str, str, float]], start: str, end: str) -> list[str]:
    # Create a graph
    graph = {location: [] for location in locations}
    for start_location, end_location, cost in routes:
        graph[start_location].append((end_location, cost))
        graph[end_location].append((start_location, cost))  # Assuming bidirectional routes

    # Initialize data structures
    queue = [(0, start, [])]
    visited = set()
    min_cost = {location: float('inf') for location in locations}
    min_cost[start] = 0

    # Dijkstra's algorithm
    while queue:
        current_cost, current_location, path = heapq.heappop(queue)
        if current_location in visited:
            continue
        path = path + [current_location]
        if current_location == end:
            return path
        visited.add(current_location)

        for neighbor, cost in graph[current_location]:
            if neighbor not in visited:
                old_cost = min_cost[neighbor]
                new_cost = current_cost + cost
                if new_cost < old_cost:
                    min_cost[neighbor] = new_cost
                    heapq.heappush(queue, (new_cost, neighbor, path))

    return []
```

