import math

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_mersenne_prime(num: int) -> bool:
    if num % 2 == 0:
        return False
    m = num + 1
    if m & (m - 1) != 0:
        return False
    p = int(math.log2(m))
    return is_prime(p)
```

