from collections import Counter
from typing import List, Tuple

class WordCountEngine:
    def __init__(self, text: str):
        self.text = text.lower()
        self.word_count = None

    def count_words(self):
        words = self.text.split()
        self.word_count = Counter(words)

    def get_top_k_words(self, k: int) -> List[Tuple[str, int]]:
        if self.word_count is None:
            raise ValueError("count_words method must be called before get_top_k_words")
        return self.word_count.most_common(k)
```

