from typing import List, Tuple

def find_top_customers(transactions: List[Tuple[str, str]]) -> List[str]:
    order_count = {}
    for customer_id, order_id in transactions:
        if customer_id not in order_count:
            order_count[customer_id] = set()
        order_count[customer_id].add(order_id)

    max_orders = max(len(orders) for orders in order_count.values())
    top_customers = [customer for customer, orders in order_count.items() if len(orders) == max_orders]
    top_customers.sort()
    return top_customers
```

