from typing import List

def max_profit_with_cooldown(prices: List[int]) -> int:
    if not prices:
        return 0

    n = len(prices)
    hold, not_hold, cooldown = -prices[0], 0, 0

    for i in range(1, n):
        hold, not_hold, cooldown = max(hold, cooldown - prices[i]), max(not_hold, hold + prices[i]), max(cooldown, not_hold)

    return max(not_hold, cooldown)
```

