import heapq

def find_shortest_path(graph, start, goal, discount):
    pq = [(0, start, [])]
    edge_count = {}

    while pq:
        (cost, node, path) = heapq.heappop(pq)
        path = path + [node]

        if node == goal:
            return path

        for neighbor, weight in graph[node]:
            new_cost = cost + weight
            edge_key = (node, neighbor)

            if edge_key in edge_count:
                if edge_count[edge_key] % 2 == 0:
                    new_cost *= discount

            if neighbor not in edge_count or new_cost < edge_count[neighbor]:
                edge_count[neighbor] = new_cost
                heapq.heappush(pq, (new_cost, neighbor, path))

    return []
```

