import heapq

def find_shortest_path(graph, start, goal, discount):
    # Priority queue for Dijkstra's algorithm
    pq = [(0, start, [])]
    # Dictionary to store the shortest path cost to each node
    shortest_path_costs = {node: float('inf') for node in graph}
    shortest_path_costs[start] = 0
    # Dictionary to store the number of times each edge has been traversed
    edge_traversals = {}

    while pq:
        current_cost, current_node, path = heapq.heappop(pq)
        path = path + [current_node]

        if current_node == goal:
            return path

        for neighbor, cost in graph[current_node]:
            new_cost = current_cost + cost
            if new_cost < shortest_path_costs[neighbor]:
                shortest_path_costs[neighbor] = new_cost
                heapq.heappush(pq, (new_cost, neighbor, path))

                # Check if the edge has been traversed an even number of times
                edge_key = (current_node, neighbor)
                if edge_key in edge_traversals:
                    if edge_traversals[edge_key] % 2 == 0:
                        new_cost *= discount
                edge_traversals[edge_key] = edge_traversals.get(edge_key, 0) + 1

    return []
