import heapq

def find_shortest_path(graph: dict[int, list[tuple[int, int]]], start: int, goal: int, discount: float) -> list[int]:
    pq = [(0, start, [])]
    visited = set()
    edge_count = {edge: 0 for node in graph for edge in graph[node]}

    while pq:
        cost, node, path = heapq.heappop(pq)
        path = path + [node]

        if node == goal:
            return path

        if node in visited:
            continue
        visited.add(node)

        for neighbor, edge_cost in graph[node]:
            new_cost = cost + edge_cost
            if edge_count[(node, neighbor)] % 2 == 1:
                new_cost *= (1 - discount)
            heapq.heappush(pq, (new_cost, neighbor, path))
            edge_count[(node, neighbor)] += 1
            edge_count[(neighbor, node)] += 1

    return []
