    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        if current_node == goal:
            return path

        for neighbor, cost in graph[current_node]:
            new_distance = current_distance + cost
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                # Apply discount if the edge has been traversed an even number of times
                if traversals[(current_node, neighbor)] % 2 == 0:
                    new_distance *= (1 - discount)
                heapq.heappush(pq, (new_distance, neighbor, path + [neighbor]))
                traversals[(current_node, neighbor)] += 1
                traversals[(neighbor, current_node)] += 1

    return []
