def combination_sum(nums: list[int], target: int) -> list[list[int]]:
    def backtrack(start, target, path):
        if target == 0:
            result.append(path)
            return
        if target < 0:
            return
        for i in range(start, len(nums)):
            backtrack(i, target - nums[i], path + [nums[i]])

    nums.sort()
    result = []
    backtrack(0, target, [])
    return result
