import re
from operator import add, sub, mul, truediv

def evaluate_expression(expr):
    expr = re.sub(r'\s+', '', expr)  # Remove whitespace
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\(|\)', expr)

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(add(left, right))
        elif operator == '-':
            values.append(sub(left, right))
        elif operator == '*':
            values.append(mul(left, right))
        elif operator == '/':
            if right == 0:
                return "Error: Division by zero"
            values.append(truediv(left, right))

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        return precedence[op1] > precedence[op2]

    operators = []
    values = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit():
            values.append(int(token))
        elif token in '+-*/':
            while (operators and operators[-1] != '(' and
                   greater_precedence(operators[-1], token)):
                apply_operator(operators, values)
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        i += 1

    while operators:
        result = apply_operator(operators, values)
        if isinstance(result, str):
            return result

    return values[0]
```

