def process_operations(lst: list, operations: list) -> list:
    if not isinstance(lst, list):
        raise TypeError("List must be provided as input.")

    for operation in operations:
        if not isinstance(operation, tuple) or len(operation) < 1:
            raise ValueError("Operation not correctly formatted or unsupported.")

        op_type, *params = operation
        if op_type == 'append':
            if len(params) != 1:
                raise ValueError("Append operation requires exactly one parameter.")
            lst.append(params[0])
        elif op_type == 'insert':
            if len(params) != 2:
                raise ValueError("Insert operation requires exactly two parameters.")
            index, value = params
            if index < 0 or index > len(lst):
                raise IndexError("Insert operation index out of range.")
            lst.insert(index, value)
        elif op_type == 'delete':
            if len(params) != 1:
                raise ValueError("Delete operation requires exactly one parameter.")
            index = params[0]
            if index < 0 or index >= len(lst):
                raise IndexError("Delete operation index out of range.")
            del lst[index]
        elif op_type == 'reverse':
            lst.reverse()
        else:
            raise ValueError("Operation not correctly formatted or unsupported.")

    return lst
```

