def find_sum_of_powers(n: int) -> list:
    powers = [2**i for i in range(20) if 2**i <= n]  # Generate powers of 2 up to n
    for i in range(len(powers)):
        for j in range(i + 1, len(powers)):
            if powers[i] + powers[j] == n:
                return [(powers[i], powers[j])]
    return []
```

