def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    import sys
    INF = sys.maxsize
    dp = [[INF] * (1 << n) for _ in range(n)]
    dp[0][1] = 0

    for mask in range(1 << n):
        for u in range(n):
            if mask & (1 << u):
                for v in range(n):
                    if u != v and mask & (1 << v):
                        dp[v][mask] = min(dp[v][mask], dp[u][mask ^ (1 << u)] + distances[u][v])

    return min(dp[u][(1 << n) - 1] + distances[u][0] for u in range(n))
