def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    # Initialize the DP table with infinity
    dp = [[float('inf')] * (1 << n) for _ in range(n)]
    # Starting point from depot (0) with no visited cities (1 << 0)
    dp[0][1] = 0

    # Iterate over all possible subsets of cities
    for mask in range(1 << n):
        for u in range(n):
            if (mask & (1 << u)) > 0:
                for v in range(n):
                    if (mask & (1 << v)) == 0:
                        dp[v][mask | (1 << v)] = min(dp[v][mask | (1 << v)], dp[u][mask] + distances[u][v])

    # Find the minimum distance to return to the depot (0) with all cities visited
    min_distance = float('inf')
    for v in range(1, n):
        min_distance = min(min_distance, dp[v][(1 << n) - 1] + distances[v][0])

    return min_distance
