    dp = [[math.inf] * (1 << n) for _ in range(n)]

    # Starting point: depot (0) with no visited locations (mask 1)
    dp[0][1] = 0

    # Iterate over all possible states
    for mask in range(1 << n):
        for u in range(n):
            if mask & (1 << u):
                for v in range(n):
                    if v != u and mask & (1 << v):
                        new_mask = mask ^ (1 << u)
                        dp[v][new_mask] = min(dp[v][new_mask], dp[u][mask] + distances[u][v])

    # Find the minimum distance to return to the depot (0) with all locations visited
    min_distance = math.inf
    for u in range(n):
        min_distance = min(min_distance, dp[u][(1 << n) - 1] + distances[u][0])

