import math

def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    # Initialize the DP table with infinity
    dp = [[math.inf] * (1 << n) for _ in range(n)]
    # Base case: distance from depot to itself is 0
    for i in range(n):
        dp[i][1 << i] = 0

    # Fill the DP table
    for mask in range(1 << n):
        for i in range(n):
            if mask & (1 << i):
                for j in range(n):
                    if j != i and mask & (1 << j):
                        dp[j][mask] = min(dp[j][mask], dp[i][mask ^ (1 << i)] + distances[i][j])

    # Find the minimum distance to return to the depot
    min_distance = math.inf
    for i in range(n):
        min_distance = min(min_distance, dp[i][(1 << n) - 1] + distances[i][0])

    return min_distance
