from typing import List

def optimal_delivery_route(n: int, distances: List[List[int]]) -> int:
    import functools

    @functools.lru_cache(None)
    def dp(mask, pos):
        if mask == (1 << n) - 1:
            return distances[pos][0]
        return min(dp(mask | (1 << i), i) + distances[pos][i] for i in range(n) if not (mask & (1 << i)))

    return dp(1, 0)
