def can_form_palindrome(s):
    from collections import Counter
    count = Counter(s)
    odd_count = sum(1 for v in count.values() if v % 2 != 0)
    if odd_count > 1:
        return ""
    mid = ""
    res = []
    for k, v in count.items():
        if v % 2 != 0:
            mid = k
        res.extend([k] * (v // 2))
    res = res + res[::-1]
    if mid:
        res.insert(len(res) // 2, mid)
    return ''.join(res)
```

