def can_form_palindrome(s):
    from collections import Counter
    count = Counter(s)
    odd_count = sum(1 for v in count.values() if v % 2 != 0)
    if odd_count > 1:
        return ""
    mid = ""
    result = []
    for char, freq in count.items():
        if freq % 2 != 0:
            mid = char
        result.extend([char] * (freq // 2))
    result = result + [mid] + result[::-1]
    return "".join(result)
```

