def subarray_with_zero_sum(arr):
    sum_indices = {}
    current_sum = 0
    for i, num in enumerate(arr):
        current_sum += num
        if current_sum == 0:
            return (0, i)
        if current_sum in sum_indices:
            return (sum_indices[current_sum] + 1, i)
        sum_indices[current_sum] = i
    return None
