def longest_subarray_with_same_diff(arr: List[int]) -> int:
    if not arr:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if arr[i] - arr[i - 1] == arr[1] - arr[0]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length
