def find_kth_perfect_number(k: int) -> int:
    if k <= 0:
        return -1

    def find_divisors(n):
        divisors = [1]
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return divisors

    def is_perfect_number(n):
        return sum(find_divisors(n)) == n

    count = 0
    num = 2
    while True:
        if is_perfect_number(num):
            count += 1
            if count == k:
                return num
        num += 1

# Example usage:
# print(find_kth_perfect_number(1))  # Output: 6
# print(find_kth_perfect_number(2))  # Output: 28
