def longest_increasing_subsequence(arr):
    if not arr:
        return 0  # Edge case: empty array

    n = len(arr)
    lis = [1] * n  # Initialize the list to store the length of LIS ending at each index

    # Compute the length of LIS for each element
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The length of the longest increasing subsequence is the maximum value in lis
    return max(lis)
```

