def extract_html_content(html: str, tag: str) -> list[str]:
    start_tag = f"<{tag}>"
    end_tag = f"</{tag}>"
    start_indices = [i for i in range(len(html)) if html.startswith(start_tag, i)]
    end_indices = [i for i in range(len(html)) if html.startswith(end_tag, i)]

    if not start_indices or not end_indices:
        return []

    result = []
    stack = []
    for start in start_indices:
        for end in end_indices:
            if start < end and end > start:
                if not stack:
                    stack.append((start, end))
                else:
                    if stack[-1][1] < start:
                        stack.append((start, end))
                    else:
                        break
            else:
                break

    for start, end in stack:
        content = html[start + len(start_tag):end]
        result.append(content)

    return result
```

