def extract_html_content(html: str, tag: str) -> list[str]:
    stack = []
    result = []
    current_content = []
    in_tag = False
    tag_name = ""

    for char in html:
        if char == '<':
            if in_tag:
                if tag_name == tag:
                    stack.append(''.join(current_content))
                    current_content = []
                in_tag = False
            else:
                in_tag = True
                tag_name = ""
        elif char == '>':
            if in_tag:
                if tag_name == tag:
                    stack.append(''.join(current_content))
                    current_content = []
                else:
                    current_content = []
                in_tag = False
        elif in_tag:
            tag_name += char
        elif not in_tag:
            if stack and stack[-1] == tag:
                current_content.append(char)
            elif stack:
                result.append(''.join(current_content))
                current_content = []

    return result
