    def evaluate(tokens):
        stack = []
        operator = '+'
        num = 0

        for token in tokens:
            if token.isdigit():
                num = num * 10 + int(token)
            if token in "+-*/" or token == ')' or not token:
                if operator == '+':
                    stack.append(num)
                elif operator == '-':
                    stack.append(-num)
                elif operator == '*':
                    stack.append(stack.pop() * num)
                elif operator == '/':
                    stack.append(int(stack.pop() / num))
                operator = token
                num = 0
            if token == '(':
                num, temp = evaluate(tokens[1:])
                tokens = temp

        return sum(stack), tokens[1:] if tokens else tokens

    tokens = expression.replace('(', ' ( ').replace(')', ' ) ').split()
    return evaluate(tokens)[0]
