from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.files = {}
        self.directories = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files[id] = size
        else:
            self.directories[id] = {'size': 0, 'children': set()}
        if parent_id is not None:
            if parent_id in self.directories:
                self.directories[parent_id]['children'].add(id)
                if not is_file:
                    self.directories[id]['parent'] = parent_id

    def delete(self, id: int) -> None:
        if id in self.files:
            del self.files[id]
        elif id in self.directories:
            for child in self.directories[id]['children']:
                self.delete(child)
            del self.directories[id]

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]
        elif id in self.directories:
            if self.directories[id]['size'] == 0:
                for child in self.directories[id]['children']:
                    self.directories[id]['size'] += self.get_size(child)
            return self.directories[id]['size']
        return 0
