from typing import Optional

class FileSystemSimulator:
    def __init__(self) -> None:
        self.files = {}
        self.directories = {}

    def create(self, id: int, size: int, parent_id: Optional[int] = None, is_file: bool = True) -> None:
        if is_file:
            self.files[id] = size
        else:
            self.directories[id] = {'size': 0, 'contents': {}}
        if parent_id is not None:
            if parent_id in self.directories:
                self.directories[parent_id]['contents'][id] = self.directories[id] if not is_file else self.files[id]
                if not is_file:
                    self.directories[parent_id]['size'] += self.directories[id]['size']
            else:
                raise ValueError("Parent directory does not exist")

    def delete(self, id: int) -> None:
        if id in self.files:
            del self.files[id]
        elif id in self.directories:
            for content_id in self.directories[id]['contents']:
                if content_id in self.directories:
                    self.directories[id]['size'] -= self.directories[content_id]['size']
                else:
                    self.directories[id]['size'] -= self.files[content_id]
            del self.directories[id]

    def get_size(self, id: int) -> int:
        if id in self.files:
            return self.files[id]
        elif id in self.directories:
            return self.directories[id]['size']
        else:
            raise ValueError("File or directory does not exist")
