def generatePalindromicSubstrings(s):
    def is_palindrome(sub):
        return sub == sub[::-1]

    n = len(s)
    palindromes = set()

    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            if is_palindrome(substring):
                palindromes.add(substring)

    return sorted(list(palindromes))
