def validate_isbn_10(isbn: str) -> bool:
    total = 0
    for i in range(9):
        total += (10 - i) * int(isbn[i])
    check_digit = int(isbn[9]) if isbn[9] != 'X' else 10
    return (total + check_digit) % 11 == 0

def validate_isbn_13(isbn: str) -> bool:
    total = 0
    for i in range(13):
        total += (1 if i % 2 == 0 else 3) * int(isbn[i])
    return total % 10 == 0
