        total = sum((10 - i) * int(isbn[i]) for i in range(9)) + (10 if isbn[-1] == 'X' else int(isbn[-1]))
        return total % 11 == 0
    elif len(isbn) == 13:
        if not isbn.isdigit():
            return False
        total = sum((1 if i % 2 == 0 else 3) * int(isbn[i]) for i in range(13))
        return total % 10 == 0
    else:
        return False
```

