def validate_isbn(isbn: str) -> bool:
    isbn = isbn.replace('-', '')
    if len(isbn) == 10:
        return validate_isbn10(isbn)
    elif len(isbn) == 13:
        return validate_isbn13(isbn)
    return False

def validate_isbn10(isbn: str) -> bool:
    total = 0
    for i in range(9):
        total += (10 - i) * int(isbn[i])
    check_digit = isbn[9]
    if check_digit == 'X':
        total += 10
    else:
        total += int(check_digit)
    return total % 11 == 0

def validate_isbn13(isbn: str) -> bool:
    total = 0
    for i in range(13):
        weight = 3 if i % 2 else 1
        total += weight * int(isbn[i])
    return total % 10 == 0
