def tribonacci(n):
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1

    # Initialize the first three terms of the sequence
    a, b, c = 0, 1, 1

    # Compute the nth term using an iterative approach
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c

    return c
```

