def is_valid_rotation(matrix):
    n = len(matrix)
    rotated = [[0] * n for _ in range(n)]

    def rotate(matrix):
        for i in range(n):
            for j in range(n):
                rotated[j][n - 1 - i] = matrix[i][j]
        return rotated

    original = [row[:] for row in matrix]
    for _ in range(3):
        matrix = rotate(matrix)
        if matrix == original:
            return True
    return False
```

