def can_segment_string(s, k):
    n = len(s)
    if n % k != 0:
        return []

    def is_unique(word):
        return len(set(word)) == len(word)

    for i in range(0, n, k):
        word = s[i:i+k]
        if not is_unique(word):
            return []

    return [s[i:i+k] for i in range(0, n, k)]
