def is_perfect_shuffle(str1, str2, shuffled_str):
    len1 = len(str1)
    len2 = len(str2)
    len_shuffled = len(shuffled_str)

    if len_shuffled != len1 + len2:
        return False

    dp = [[False] * (len2 + 1) for _ in range(len1 + 1)]
    dp[0][0] = True

    for i in range(len1 + 1):
        for j in range(len2 + 1):
            if i > 0:
                dp[i][j] = dp[i][j] or (dp[i - 1][j] and str1[i - 1] == shuffled_str[i + j - 1])
            if j > 0:
                dp[i][j] = dp[i][j] or (dp[i][j - 1] and str2[j - 1] == shuffled_str[i + j - 1])

    return dp[len1][len2]
```

