    len_s2 = len(s2)
    len_s = len(s)

    if len_s != len_s1 + len_s2:
        return False

    # Initialize a 2D list with False values
    dp = [[False] * (len_s2 + 1) for _ in range(len_s1 + 1)]

    # Base case: an empty string is a perfect shuffle of two empty strings
    dp[0][0] = True

    # Fill the dp table
    for i in range(len_s1 + 1):
        for j in range(len_s2 + 1):
            if i > 0:
                dp[i][j] = dp[i][j] or (dp[i - 1][j] and s1[i - 1] == s[i - 1])
            if j > 0:
                dp[i][j] = dp[i][j] or (dp[i][j - 1] and s2[j - 1] == s[i + j - 1])

    return dp[len_s1][len_s2]
