    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        start, _, _ = serve_time[i - 1]
        j = i - 2
        while j >= 0 and serve_time[j][0][1] <= start:
            dp[i] = max(dp[i], dp[j + 1] + serve_time[i - 1][1])
            j -= 1

    return dp[n]
