class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients

    def __add__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        result = [0] * max_len
        for i in range(max_len):
            result[i] = (self.coefficients[i] if i < len(self.coefficients) else 0) + \
                         (other.coefficients[i] if i < len(other.coefficients) else 0)
        return Polynomial(result)

    def __sub__(self, other):
        max_len = max(len(self.coefficients), len(other.coefficients))
        result = [0] * max_len
        for i in range(max_len):
            result[i] = (self.coefficients[i] if i < len(self.coefficients) else 0) - \
                         (other.coefficients[i] if i < len(other.coefficients) else 0)
        return Polynomial(result)

    def __mul__(self, other):
        result = [0] * (len(self.coefficients) + len(other.coefficients) - 1)
        for i in range(len(self.coefficients)):
            for j in range(len(other.coefficients)):
                result[i + j] += self.coefficients[i] * other.coefficients[j]
        return Polynomial(result)

    def evaluate(self, x):
        return sum(coef * x**i for i, coef in enumerate(self.coefficients))

    def __str__(self):
        terms = []
        for i, coef in enumerate(self.coefficients):
            if coef != 0:
                if i == 0:
                    terms.append(f"{coef}")
                elif i == 1:
                    terms.append(f"{coef}x" if coef != 1 else "x")
                else:
                    terms.append(f"{coef}x^{i}" if coef != 1 else f"x^{i}")
        return " + ".join(terms)

