def lastPersonStanding(N: int, k: int) -> int:
    def josephus(n, k):
        if n == 1:
            return 0
        else:
            return (josephus(n - 1, k) + k) % n

    # The position returned by josephus() is 0 based, so we add 1 to get the 1 based position
    return josephus(N, k) + 1
```

