def min_add_to_make_valid(s):
    open_needed = close_needed = 0
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
            if balance < 0:
                close_needed += 1
                balance = 0
        elif char == ')':
            balance -= 1
            if balance > 0:
                open_needed += 1
                balance = 0
    return open_needed + close_needed
