def find_longest_substring(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""

    longest = ""
    start = 0
    char_index = {}

    for end in range(n):
        if s[end] in char_index and char_index[s[end]] >= start:
            start = char_index[s[end]] + 1
        char_index[s[end]] = end
        if end - start + 1 > len(longest):
            longest = s[start:end+1]

    return longest
