def permutable_palindrome(s: str) -> bool:
    # A string can be rearranged to form a palindrome if at most one character has an odd count
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    return odd_count <= 1

# Example tests
print(permutable_palindrome("carrace"))  # Should return True
print(permutable_palindrome("hello"))    # Should return False
print(permutable_palindrome("aabbcc"))   # Should return True
print(permutable_palindrome("abc"))      # Should return False
```

