def is_happy_string(s):
    vowels = set("aeiouAEIOU")
    vowel_count = 0
    consonant_count = 0
    for char in s:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1
    return vowel_count > 2 * consonant_count

