                anagrams = [m.start() for m in re.finditer(r'\b\w+\b', s) if sorted(m.group()) == sorted(word)]
                analysis_results.append(f"find_anagrams: {anagrams}")
            else:
                raise ValueError("Word must be provided for find_anagrams action")
